  }
 },
 "defaultTier": "unknown",
 "byAddress": {
  "pm@gc-example.com": "key_client",
  "estimator@gc-example.com": "key_client",
  "subcontracts@gc-example.com": "key_client",
  "garic@alphaomega-example.com": "internal",
  "principal@arch-example.com": "key_client",
  "news@arch-example.com": "key_client",
  "purchasing@example-isd.org": "client",
  "contracts@city-example.gov": "client",
  "purchasing@city-example.gov": "client",
  "purchasing@county-example.gov": "prospect",
  "civil@example-eng.com": "client",
  "developer@example-dev.com": "prospect",
  "news@drillrig-vendor.com": "vendor"
 },
 "byDomain": {
  "alphaomega-example.com": "internal",
  "aogeotech.com": "internal"
 }
};

/**
 * Priority tier lookup.
 *
 * Spec red line: "Any priority tier set by the LLM instead of the contacts lookup" is a
 * ship blocker. So there is no model anywhere in this file and there never should be.
 * Address match wins over domain match, and a miss returns the default tier with
 * tier_source 'default' so the caller can tell a real lookup from a fallback.
 *
 * Suite 3 cases: PRI-01 address hit, PRI-02 miss, PRI-03 internal hit, PRI-04 the split
 * where content routed the message to Noise but the tier stays whatever the table says.
 */

const normalize = (address) => String(address ?? '').trim().toLowerCase();

/** Pulls the address out of "Name <addr@host>" or a bare address. */
function parseAddress(input) {
	const raw = normalize(input);
	const angled = raw.match(/<([^>]+)>/);
	return angled ? angled[1].trim() : raw;
}

function domainOf(address) {
	const at = parseAddress(address).lastIndexOf('@');
	return at === -1 ? '' : parseAddress(address).slice(at + 1);
}

/**
 * @param {string} fromAddress
 * @returns {{priority_tier: string, tier_source: 'lookup'|'default', tier_rank: number, weight_floor: number, matched_on: 'address'|'domain'|null}}
 */
function lookupTier(fromAddress) {
	const address = parseAddress(fromAddress);
	const domain = domainOf(address);

	let tier = null;
	let matchedOn = null;

	if (address && Object.hasOwn(contacts.byAddress, address)) {
		tier = contacts.byAddress[address];
		matchedOn = 'address';
	} else if (domain && Object.hasOwn(contacts.byDomain, domain)) {
		tier = contacts.byDomain[domain];
		matchedOn = 'domain';
	}

	const source = tier ? 'lookup' : 'default';
	const resolved = tier ?? contacts.defaultTier;
	const meta = contacts.tiers[resolved];

	if (!meta) {
		throw new Error(`contacts.json maps ${address} to unknown tier "${resolved}"`);
	}

	return {
		priority_tier: resolved,
		tier_source: source,
		tier_rank: meta.rank,
		weight_floor: meta.weightFloor,
		matched_on: matchedOn,
	};
}

/**
 * Strips any tier-shaped field a model tried to emit. Called on every extractor result
 * before the tier lookup is merged in, so a hallucinated tier can never reach a record.
 */
const MODEL_TIER_FIELDS = [
	'priority_tier',
	'tier',
	'tier_source',
	'priority',
	'importance',
	'urgency',
	'weight',
];

function stripModelTier(extracted) {
	const clean = { ...extracted };
	const removed = [];
	for (const field of MODEL_TIER_FIELDS) {
		if (field in clean) {
			removed.push(field);
			delete clean[field];
		}
	}
	return { clean, removed };
}

// RED LINE: the tier is a table fact. No model runs in this node and none ever should.
return $input.all().map((item) => ({
  json: { ...item.json, tier: lookupTier(item.json.email.from) },
}));

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "due_date": {
      "type": [
        "string",
        "null"
      ],
      "description": "The single date AOG has to hit, as YYYY-MM-DDTHH:mm when a time is given, otherwise YYYY-MM-DD. Null when the message states no date. Never guess and never copy a date from a different message."
    },
    "primary_due_date": {
      "type": [
        "string",
        "null"
      ],
      "description": "Same value as due_date. Present so downstream jobs can read one field name when a message carries several dates."
    },
    "other_dates": {
      "type": "array",
      "description": "Every other date in the message that is not the primary due date. Pre-bid meetings, site walks, question deadlines, award dates, mobilization dates. Empty array when there are none.",
      "items": {
        "type": "object",
        "properties": {
          "label": {
            "type": "string",
            "description": "What the date is, in the message's own words, lowercased. For example: pre-bid, site walk, questions due, award, mobilization."
          },
          "date": {
            "type": "string",
            "description": "YYYY-MM-DDTHH:mm when a time is given, otherwise YYYY-MM-DD."
          }
        },
        "required": [
          "label",
          "date"
        ]
      }
    },
    "date_in_attachment": {
      "type": "boolean",
      "description": "True when the message defers its dates to an attachment or a link rather than stating them in the body. For example 'see attached RFQ for all dates'. False otherwise."
    },
    "project_name": {
      "type": [
        "string",
        "null"
      ],
      "description": "The project as named in the message, without the bid number, without the word project, and without the scope of work. From 'ITB 26-118 Geotechnical Investigation, New Elementary' the project name is 'New Elementary'. Null when no project is named."
    },
    "client_name": {
      "type": [
        "string",
        "null"
      ],
      "description": "The organization the work is for, written the way a person would say it out loud. Derive it from the signature, the letterhead or the sender domain. From purchasing@example-isd.org that is 'Example ISD'. Null when it cannot be determined from the message."
    },
    "bid_reference": {
      "type": [
        "string",
        "null"
      ],
      "description": "The solicitation number as written, for example 'ITB 26-118' or 'RFP 2026-04'. Null when the message carries none. This is the key that ties addenda back to the original opportunity."
    },
    "project_stage": {
      "type": [
        "string",
        "null"
      ],
      "description": "One of exactly: 'proposal requested', 'addendum', 'bid submitted', 'awarded', 'not awarded', 'active project', 'closeout', 'prequalification', 'none'. Use 'proposal requested' when AOG is being asked to bid or propose. Use 'active project' when the work is already underway. Null only when the message is not about a project at all."
    },
    "requested_items": {
      "type": "array",
      "description": "Concrete deliverables the sender is asking AOG to send back, one per entry, in the order requested, using the plain name of the item. Write out abbreviations: 'COI' becomes 'certificate of insurance', 'W-9' stays 'W-9'. A request to bid is the single item 'bid'. Empty array when nothing is being requested.",
      "items": {
        "type": "string"
      }
    },
    "response_needed": {
      "type": "boolean",
      "description": "True when a person is waiting on something from AOG: an answer, a document, a price, a date, a decision, or a bid. False for bulk mail, newsletters, vendor promotions, automated notifications, and messages that are purely informational with no ask."
    },
    "intro_opportunity": {
      "type": "boolean",
      "description": "True when the sender offers to introduce, refer or connect AOG to someone new. False otherwise."
    },
    "intro_target": {
      "type": [
        "string",
        "null"
      ],
      "description": "Who the introduction is to, described as the message describes them. Null when intro_opportunity is false."
    },
    "action_summary": {
      "type": "string",
      "description": "One sentence, under 25 words, saying what AOG has to do and by when. Use only facts present in the message."
    }
  },
  "required": [
    "due_date",
    "primary_due_date",
    "other_dates",
    "date_in_attachment",
    "project_name",
    "client_name",
    "bid_reference",
    "project_stage",
    "requested_items",
    "response_needed",
    "intro_opportunity",
    "intro_target",
    "action_summary"
  ]
}

