/**
 * Priority tier lookup.
 *
 * Spec red line: "Any priority tier set by the LLM instead of the contacts lookup" is a
 * ship blocker. So there is no model anywhere in this file and there never should be.
 * Address match wins over domain match, and a miss returns the default tier with
 * tier_source 'default' so the caller can tell a real lookup from a fallback.
 *
 * Suite 3 cases: PRI-01 address hit, PRI-02 miss, PRI-03 internal hit, PRI-04 the split
 * where content routed the message to Noise but the tier stays whatever the table says.
 */

const normalize = (address) => String(address ?? '').trim().toLowerCase();

/** Pulls the address out of "Name <addr@host>" or a bare address. */
function parseAddress(input) {
	const raw = normalize(input);
	const angled = raw.match(/<([^>]+)>/);
	return angled ? angled[1].trim() : raw;
}

function domainOf(address) {
	const at = parseAddress(address).lastIndexOf('@');
	return at === -1 ? '' : parseAddress(address).slice(at + 1);
}

/**
 * @param {string} fromAddress
 * @returns {{priority_tier: string, tier_source: 'lookup'|'default', tier_rank: number, weight_floor: number, matched_on: 'address'|'domain'|null}}
 */
function lookupTier(fromAddress) {
	const address = parseAddress(fromAddress);
	const domain = domainOf(address);

	let tier = null;
	let matchedOn = null;

	if (address && Object.hasOwn(contacts.byAddress, address)) {
		tier = contacts.byAddress[address];
		matchedOn = 'address';
	} else if (domain && Object.hasOwn(contacts.byDomain, domain)) {
		tier = contacts.byDomain[domain];
		matchedOn = 'domain';
	}

	const source = tier ? 'lookup' : 'default';
	const resolved = tier ?? contacts.defaultTier;
	const meta = contacts.tiers[resolved];

	if (!meta) {
		throw new Error(`contacts.json maps ${address} to unknown tier "${resolved}"`);
	}

	return {
		priority_tier: resolved,
		tier_source: source,
		tier_rank: meta.rank,
		weight_floor: meta.weightFloor,
		matched_on: matchedOn,
	};
}

/**
 * Strips any tier-shaped field a model tried to emit. Called on every extractor result
 * before the tier lookup is merged in, so a hallucinated tier can never reach a record.
 */
const MODEL_TIER_FIELDS = [
	'priority_tier',
	'tier',
	'tier_source',
	'priority',
	'importance',
	'urgency',
	'weight',
];

function stripModelTier(extracted) {
	const clean = { ...extracted };
	const removed = [];
	for (const field of MODEL_TIER_FIELDS) {
		if (field in clean) {
			removed.push(field);
			delete clean[field];
		}
	}
	return { clean, removed };
}

/**
 * Second-pass extraction. Suite 2.
 *
 * Runs after routing, on the same text the classifier saw plus a REFERENCE DATE line so
 * relative dates ("Friday", "2/14") resolve against when the mail arrived rather than
 * against whenever the job happens to run.
 *
 * Red line: "Any real deadline that the extractor records as 'no deadline'." The schema
 * pushes hard on that in both directions. A stated date must be captured. An absent date
 * must stay null with date_in_attachment set, because a null gets a human's attention and
 * an invented date does not.
 */

function buildExtractorSystemPrompt() {
	return [
		prompts.extractor,
		'',
		'Output a single JSON object matching this schema and nothing else:',
		'',
		JSON.stringify(extractorSchema, null, 2),
	].join('\n');
}

const EMPTY = {
	due_date: null,
	primary_due_date: null,
	other_dates: [],
	date_in_attachment: false,
	project_name: null,
	client_name: null,
	bid_reference: null,
	project_stage: null,
	requested_items: [],
	response_needed: false,
	intro_opportunity: false,
	intro_target: null,
	action_summary: '',
};

/** Fill gaps and keep primary_due_date in step with due_date. */
function normalizeExtraction(raw) {
	const { clean, removed } = stripModelTier(raw ?? {});
	const out = { ...EMPTY, ...clean };

	out.other_dates = Array.isArray(out.other_dates) ? out.other_dates : [];
	out.requested_items = Array.isArray(out.requested_items) ? out.requested_items : [];

	if (out.due_date && !out.primary_due_date) out.primary_due_date = out.due_date;
	if (out.primary_due_date && !out.due_date) out.due_date = out.primary_due_date;

	if (!out.intro_opportunity) out.intro_target = null;

	return { extracted: out, droppedFields: removed };
}

/**
 * @param {object} input email or thread fixture, needs receivedAt for date resolution
 * @param {object} [opts] {pass, model, category}
 */
async function extract(input, opts = {}) {
	const system = buildExtractorSystemPrompt();
	const user = [
		opts.category ? `ROUTED AS: ${opts.category}` : null,
		renderInput(input, { withReferenceDate: true }),
	]
		.filter(Boolean)
		.join('\n\n');

	const text = await callModel({
		system,
		user,
		model: opts.model ?? settings.llm.extractorModel,
		effort: settings.llm.effort.extractor,
		pass: opts.pass ?? 0,
	});

	const { extracted, droppedFields } = normalizeExtraction(parseJsonResponse(text));

	return { extracted, droppedFields };
}

